messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: contrib/pds/tif_pdsdirwrite.c
Line: 737
Function: TIFFWriteRationalArray
Bug type: null-pointer-dereference
CWE: CWE-476
Explanation: _TIFFmalloc() allocates t for 2*n uint32_t elements without checking for failure. If allocation returns NULL, t is dereferenced in t[2 * i + 0] = ..., leading to a NULL pointer dereference.

Source context:
```c
      697: /*
      698:  * Setup a directory entry of an array of RATIONAL
      699:  * or SRATIONAL and write the associated indirect values.
      700:  */
      701: static int TIFFWriteRationalArray(TIFF *tif, TIFFDataType type, ttag_t tag,
      702:                                   TIFFDirEntry *dir, uint32_t n, float *v)
      703: {
      704:     uint32_t i;
      705:     uint32_t *t;
      706:     int status;
      707: 
      708:     dir->tdir_tag = tag;
      709:     dir->tdir_type = (short)type;
      710:     dir->tdir_count = n;
      711:     t = (uint32_t *)_TIFFmalloc(2 * n * sizeof(uint32_t));
      712:     for (i = 0; i < n; i++)
      713:     {
      714:         float fv = v[i];
      715:         int sign = 1;
      716:         uint32_t den;
      717: 
      718:         if (fv < 0)
      719:         {
      720:             if (type == TIFF_RATIONAL)
      721:             {
      722:                 TIFFWarning(tif->tif_name,
      723:                             "\"%s\": Information lost writing value (%g) as "
      724:                             "(unsigned) RATIONAL",
      725:                             _TIFFFieldWithTag(tif, tag)->field_name, v);
      726:                 fv = 0;
      727:             }
      728:             else
      729:                 fv = -fv, sign = -1;
      730:         }
      731:         den = 1L;
      732:         if (fv > 0)
      733:         {
      734:             while (fv < 1L << (31 - 3) && den < 1L << (31 - 3))
      735:                 fv *= 1 << 3, den *= 1L << 3;
      736:         }
>>>   737:         t[2 * i + 0] = sign * (fv + 0.5);
      738:         t[2 * i + 1] = den;
      739:     }
      740:     status = TIFFWriteData(tif, dir, (char *)t);
      741:     _TIFFfree((char *)t);
      742:     return (status);
      743: }
      744: 
      745: static int TIFFWriteFloatArray(TIFF *tif, TIFFDataType type, ttag_t tag,
      746:                                TIFFDirEntry *dir, uint32_t n, float *v)
      747: {
      748:     dir->tdir_tag = tag;
      749:     dir->tdir_type = (short)type;
      750:     dir->tdir_count = n;
      751:     TIFFCvtNativeToIEEEFloat(tif, n, v);
      752:     if (n == 1)
      753:     {
      754:         dir->tdir_offset = *(uint32_t *)&v[0];
      755:         return (1);
      756:     }
      757:     else
      758:         return (TIFFWriteData(tif, dir, (char *)v));
      759: }
      760: 
      761: static int TIFFWriteDoubleArray(TIFF *tif, TIFFDataType type, ttag_t tag,
      762:                                 TIFFDirEntry *dir, uint32_t n, double *v)
      763: {
      764:     dir->tdir_tag = tag;
      765:     dir->tdir_type = (short)type;
      766:     dir->tdir_count = n;
      767:     TIFFCvtNativeToIEEEDouble(tif, n, v);
      768:     return (TIFFWriteData(tif, dir, (char *)v));
      769: }
      770: 
      771: /*
      772:  * Write an array of ``type'' values for a specified tag (i.e. this is a tag
      773:  * which is allowed to have different types, e.g. SMaxSampleType).
      774:  * Internally the data values are represented as double since a double can
      775:  * hold any of the TIFF tag types (yes, this should really be an abstract
      776:  * type tany_t for portability).  The data is converted into the specified
      777:  * type in a temporary buffer and then handed off to the appropriate array
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libtiff_upstream reproducer.c -L/tmp/libtiff_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libtiff_upstream
